void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await Hive.initFlutter();
  final store = FinanceStore();
  await store.load();
  runApp(ChangeNotifierProvider.value(value: store, child: const SpendWiseApp()));
}

class Txn {
  Txn({required this.id, required this.title, required this.amount, required this.date, required this.category, required this.income});
  final String id, title, category; final double amount; final DateTime date; final bool income;
  Map<String, dynamic> toJson() => {'id': id, 'title': title, 'amount': amount, 'date': date.toIso8601String(), 'category': category, 'income': income};
  factory Txn.fromJson(Map data) => Txn(id: data['id'] as String, title: data['title'] as String, amount: (data['amount'] as num).toDouble(), date: DateTime.parse(data['date'] as String), category: data['category'] as String, income: data['income'] as bool);
}

class FinanceStore extends ChangeNotifier {
  late Box<String> _box; List<Txn> transactions = []; double budget = 1200; bool dark = false;
  Future<void> load() async { _box = await Hive.openBox<String>('spendwise'); transactions = _box.values.map((v) => Txn.fromJson(Map<String, dynamic>.from(jsonDecode(v)))).toList()..sort((a,b)=>b.date.compareTo(a.date)); final p=await SharedPreferences.getInstance(); budget=p.getDouble('budget')??1200; dark=p.getBool('dark')??false; notifyListeners(); }
  Future<void> _save() async { await _box.clear(); for(final t in transactions) { await _box.put(t.id, jsonEncode(t.toJson())); } notifyListeners(); }
  Future<void> upsert(Txn t) async { transactions.removeWhere((x)=>x.id==t.id); transactions.add(t); transactions.sort((a,b)=>b.date.compareTo(a.date)); await _save(); }
  Future<void> remove(String id) async { transactions.removeWhere((x)=>x.id==id); await _save(); }
  Future<void> setBudget(double value) async { budget=value; (await SharedPreferences.getInstance()).setDouble('budget', value); notifyListeners(); }
  Future<void> toggleTheme() async { dark=!dark; (await SharedPreferences.getInstance()).setBool('dark',dark); notifyListeners(); }
  List<Txn> get month => transactions.where((t)=>t.date.year==DateTime.now().year&&t.date.month==DateTime.now().month).toList();
  double get income => month.where((t)=>t.income).fold(0,(s,t)=>s+t.amount); double get expenses=>month.where((t)=>!t.income).fold(0,(s,t)=>s+t.amount); double get balance=>transactions.fold(0,(s,t)=>s+(t.income?t.amount:-t.amount));
  Map<String,double> get spending { final m=<String,double>{}; for(final t in month.where((x)=>!x.income)){m[t.category]=(m[t.category]??0)+t.amount;} return m; }
  Future<void> demo() async { if(transactions.isNotEmpty)return; final n=DateTime.now(); transactions=[Txn(id:'1',title:'Salary',amount:3400,date:n,category:'Income',income:true),Txn(id:'2',title:'Fresh Market',amount:86,date:n.subtract(const Duration(days:1)),category:'Food',income:false),Txn(id:'3',title:'Metro Card',amount:42,date:n.subtract(const Duration(days:2)),category:'Transport',income:false),Txn(id:'4',title:'Internet',amount:55,date:n.subtract(const Duration(days:5)),category:'Bills',income:false),Txn(id:'5',title:'Freelance project',amount:320,date:n.subtract(const Duration(days:6)),category:'Income',income:true)]; await _save(); }
}

