class Transactions extends StatefulWidget { const Transactions({super.key}); @override State<Transactions> createState()=>_TransactionsState();} class _TransactionsState extends State<Transactions>{String query='';String cat='All';@override Widget build(BuildContext c){final s=c.watch<FinanceStore>();final cats=['All',...{...s.transactions.map((x)=>x.category)}];final list=s.transactions.where((t)=>(cat=='All'||t.category==cat)&&t.title.toLowerCase().contains(query.toLowerCase())).toList();return Scaffold(floatingActionButton:FloatingActionButton.extended(onPressed:()=>showTxn(c,null),icon:const Icon(Icons.add),label:const Text('Add')),body:ListView(padding:const EdgeInsets.all(20),children:[Text('Transactions',style:Theme.of(c).textTheme.headlineMedium),const SizedBox(height:16),TextField(onChanged:(v)=>setState(()=>query=v),decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Search your history',border:OutlineInputBorder(borderRadius:BorderRadius.all(Radius.circular(18)))),),const SizedBox(height:12),SingleChildScrollView(scrollDirection:Axis.horizontal,child:Row(children:cats.map((x)=>Padding(padding:const EdgeInsets.only(right:8),child:ChoiceChip(label:Text(x),selected:cat==x,onSelected:(_)=>setState(()=>cat=x)))).toList())),const SizedBox(height:14),if(list.isEmpty) Empty(onDemo:s.demo) else ...list.map((t)=>TxnTile(t:t,onEdit:()=>showTxn(c,t))),const SizedBox(height:80)]));}}
