class Budget extends StatelessWidget{const Budget({super.key});@override Widget build(BuildContext c){final s=c.watch<FinanceStore>();final p=s.budget==0?0.0:(s.expenses/s.budget).clamp(0.0,1.0).toDouble();return ListView(padding:const EdgeInsets.all(20),children:[Text('Spending plan',style:Theme.of(c).textTheme.headlineMedium),const SizedBox(height:20),Card(child:Padding(padding:const EdgeInsets.all(24),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${(p*100).round()}% of monthly budget used',style:Theme.of(c).textTheme.titleLarge),const SizedBox(height:14),LinearProgressIndicator(value:p,minHeight:14,borderRadius:BorderRadius.circular(10),color:p>.8?Colors.orange:Colors.teal),const SizedBox(height:18),Text('RM ${s.expenses.toStringAsFixed(0)} spent of RM ${s.budget.toStringAsFixed(0)}'),if(p>.8)const Padding(padding:EdgeInsets.only(top:10),child:Text('Heads up: you are approaching your limit.',style:TextStyle(color:Colors.orange,fontWeight:FontWeight.bold)))])),const SizedBox(height:20),FilledButton.icon(onPressed:()async{final v=await amountDialog(c,'Set monthly budget',s.budget);if(v!=null)s.setBudget(v);},icon:const Icon(Icons.edit),label:const Text('Adjust budget')),const SizedBox(height:14),OutlinedButton.icon(onPressed:s.demo,icon:const Icon(Icons.auto_awesome),label:const Text('Load portfolio demo data'))]);}}
