void showTxn(BuildContext c,Txn? old){final form=GlobalKey<FormState>();final title=TextEditingController(text:old?.title);final amount=TextEditingController(text:old?.amount.toString());var income=old?.income??false;var category=old?.category??'Food';showModalBottomSheet(context:c,isScrollControlled:true,builder:(ctx)=>Padding(padding:EdgeInsets.fromLTRB(20,20,20,20+MediaQuery.of(ctx).viewInsets.bottom),child:StatefulBuilder(builder:(ctx,set)=>Form(key:form,child:Wrap(children:[Text(old==null?'Add transaction':'Edit transaction',style:Theme.of(ctx).textTheme.titleLarge),TextFormField(controller:title,decoration:const InputDecoration(labelText:'Description'),validator:(v)=>v==null||v.trim().isEmpty?'Enter a description':null),TextFormField(controller:amount,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Amount'),validator:(v)=>double.tryParse(v??'')==null?'Enter a valid amount':null),DropdownButtonFormField(value:category,items:['Food','Transport','Bills','Shopping','Health','Income'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>set(()=>category=v!)),SwitchListTile(value:income,onChanged:(v)=>set(()=>income=v),title:const Text('This is income')),Row(children:[if(old!=null)TextButton(onPressed:()async{await c.read<FinanceStore>().remove(old.id);if(ctx.mounted)Navigator.pop(ctx);},child:const Text('Delete',style:TextStyle(color:Colors.red))),const Spacer(),FilledButton(onPressed:()async{if(!form.currentState!.validate())return;await c.read<FinanceStore>().upsert(Txn(id:old?.id??DateTime.now().microsecondsSinceEpoch.toString(),title:title.text.trim(),amount:double.parse(amount.text),date:old?.date??DateTime.now(),category:income?'Income':category,income:income));if(ctx.mounted)Navigator.pop(ctx);},child:const Text('Save'))])]))));}
